from pathlib import Path

ROOT = Path('.')
for f in sorted(glob.glob(str(ROOT / 'bench/logs/*/runner_state.json'))):
    if os.path.getsize(f) > 60_000_000:
        continue
    try:
        data = json.loads(open(f, errors='ignore').read())
    except:
        continue

    def walk(o, depth=0):
        if isinstance(o, dict):
            sk = o.get('sk_result')
            if isinstance(sk, dict) and sk.get('tristate') == 'ADMISSIBLE':
                # Print the keys of the first one we find
                print("sk_result keys:", sorted(sk.keys()))
                # Print first 3 entries
                for k in sorted(sk.keys()):
                    print(f"  {k}: {sk[k]}")
                return True
            for v in o.values():
                if walk(v, depth+1):
                    return True
        elif isinstance(o, list):
            for v in o:
                if walk(v, depth+1):
                    return True
        return False
    if walk(data):
        break"}
